  if(&sprite==&ChompArt::BtnPTime)return arcade_btn_p_time;
  if(&sprite==&ChompArt::IconPlay)return arcade_icon_play;
  if(&sprite==&ChompArt::IconPause)return arcade_icon_pause;
  if(&sprite==&ChompArt::IconSpeed)return arcade_icon_speed;
  if(&sprite==&ChompArt::IconForward)return arcade_icon_forward;
  if(&sprite==&ChompArt::IconReverse)return arcade_icon_reverse;
  if(&sprite==&ChompArt::IconFx1Echo)return arcade_icon_fx1_echo;
  if(&sprite==&ChompArt::IconFx2Stutter)return arcade_icon_fx2_stutter;
  if(&sprite==&ChompArt::IconFx3Robot)return arcade_icon_fx3_robot;
  if(&sprite==&ChompArt::IconLoopOff)return arcade_icon_loop_off;
  if(&sprite==&ChompArt::IconLoopOne)return arcade_icon_loop_one;
  if(&sprite==&ChompArt::IconLoopAll)return arcade_icon_loop_all;
  if(&sprite==&ChompArt::IconBattery)return arcade_icon_battery;
  if(&sprite==&ChompArt::IconRecordDot)return arcade_icon_record_dot;
  if(&sprite==&ChompArt::IconSettings)return arcade_icon_settings;
  if(&sprite==&ChompArt::IconEffects)return arcade_icon_effects;
  if(&sprite==&ChompArt::IconInfo)return arcade_icon_info;
  if(&sprite==&ChompArt::IconTracks)return arcade_icon_tracks;
  if(&sprite==&ChompArt::IconMenuBack)return arcade_icon_menu_back;
  if(&sprite==&ChompArt::IconFxEcho)return arcade_icon_fx_echo;
  if(&sprite==&ChompArt::IconFxStutter)return arcade_icon_fx_stutter;
